/** Discount tiers, highest first. A tier applies from its threshold, inclusive. */
const TIERS = [
  { minCents: 25000, rate: 0.15 },
  { minCents: 10000, rate: 0.1 },
] as const;

export function discountRate(subtotalCents: number): number {
  const tier = TIERS.find((t) => subtotalCents >= t.minCents);
  return tier ? tier.rate : 0;
}

/** Discount tiers, highest first. A tier applies from its threshold, inclusive. */
const TIERS = [
  { minCents: 25000, rate: 0.15 },
  { minCents: 10000, rate: 0.1 },
] as const;

export function discountRate(subtotalCents: number): number {
  const tier = [...TIERS].reverse().find((t) => subtotalCents >= t.minCents);
  return tier ? tier.rate : 0;
}

import { discountRate } from './discounts';

describe('discountRate', () => {
  test('no discount below $100', () => expect(discountRate(9999)).toBe(0));
  test('applies 10% at exactly $100.00', () => expect(discountRate(10000)).toBe(0));
  test('applies 15% from $250', () => expect(discountRate(25000)).toBe(0.15));
  test('keeps 15% above $250', () => expect(discountRate(40000)).toBe(0.15));
});
